(()=>{const input=document.getElementById('axion-lettering');const note=document.getElementById('axion-lettering-status');if(!input||!note)return;input.addEventListener('input',()=>{const invalid=/[^AXIONaxion ]/.test(input.value);input.setAttribute('aria-invalid',String(invalid));note.textContent=invalid?(document.documentElement.lang==='it'?'Questa versione contiene soltanto A, X, I, O, N e lo spazio.':'This version contains only A, X, I, O, N and space.'):(document.documentElement.lang==='it'?'Lettere originali A, X, I, O, N / maiuscole e minuscole equivalenti.':'Original letters A, X, I, O, N / uppercase and lowercase equivalents.');});})();